import type { Player } from './index';

export const squad: Player[] = [
  // Porteros
  { number: 1, name: 'Matej Kovar', position: 'GK', age: 26, club: 'PSV Eindhoven', bio: {"es":"Favorito de la selección checa desde el pasado otoño. En pocos días ayudó a conseguir dos éxitos en los play-offs mediante la tanda de penaltis. Hasta entonces sólo había atajado un penalti en el fútbol nacional, pero en la lucha por una plaza para el Mundial brilló como ningún otro en la selección checa. “Parece un sueño”, dijo tras las victorias sobre la República de Irlanda y Dinamarca. Kovar es un gran talento, tranquilo por naturaleza y mayoritariamente flemático. Cuando era adolescente, dejó un pequeño pueblo checo para unirse al Manchester United. Desde entonces ha ganado tres títulos de liga en tres países diferentes: Chequia, Alemania y Holanda. Aunque suele ser tranquilo y modesto, se destaca en los grandes momentos y los entrenadores bromean diciendo que trae suerte. “No fue una gran suerte, simplemente hice mis deberes”, dijo mientras todo el país lo elogiaba. Aún así, persisten las especulaciones sobre si será el portero titular para la Copa del Mundo.","en":"A favourite in the Czech national team since last autumn. In the space of a few days he helped seal two play-off successes via penalty shootouts. Before then he had only saved one spot-kick in domestic football, but he excelled in the scrap for a World Cup spot like nobody else in the Czech squad. “It feels like a dream,” he said after the wins over Republic of Ireland and Denmark. Kovar is a huge talent, calm by nature and mostly phlegmatic. As a teenager, he left a small Czech town to join Manchester United. He has since won three league titles in three different countries: Czechia, Germany and the Netherlands. Although he’s usually quiet and modest, he thrives in the big moments and coaches joke that he brings luck. “It wasn’t any great luck, I simply did my homework,” he said while the whole country was lauding him. Still, speculation persists over whether he will be the first-choice goalkeeper for the World Cup."} },
  { number: 16, name: 'Jindrich Stanek', position: 'GK', age: 30, club: 'Slavia Prague', bio: {"es":"Stanek nunca ha recibido nada gratis en su carrera. Comenzó como jugador de hockey sobre hielo y era un delantero prometedor, talento que heredó de su padre. Pero decidió abandonar el hielo en busca de una carrera futbolística y se fue directamente del Sparta a Inglaterra, donde fue portero suplente en el Everton, enfrentándose a tiros de Romelu Lukaku, Kevin Mirallas y Samuel Eto'o en los entrenamientos. \"Me sentí como en otro mundo. Estaba recibiendo una paliza, pero no quería rendirme\", recordó más tarde. Soñaba con seguir los pasos de su compatriota Petr Cech, pero tuvo que tomar el camino más largo. Incluso pasó una temporada en la tercera división checa para ganar confianza. \"En retrospectiva, me siento como un gato con siete vidas\", dijo sobre su carrera nómada. \"Por eso, cuando voy al zoológico, paso la mayor parte del tiempo con los tigres. Busco inspiración en ellos\". Finalmente se instaló en el Viktoria Plzen, donde despegó su carrera, lo que le llevó a mudarse al Slavia Praga en 2024.","en":"Stanek has never got anything for free in his career. He started out as an ice hockey player and was a promising forward, a talent he inherited from his father. But he chose to leave the ice in pursuit of a football career and went straight from Sparta to England, where he was a backup goalkeeper at Everton, facing shots from Romelu Lukaku, Kevin Mirallas and Samuel Eto’o in training. “I felt like I was in another world. I was taking a battering, but I didn’t want to give up,” he later recalled. He dreamed of following in the footsteps of compatriot Petr Cech, but had to take the long way round. He even spent a season in the Czech third division to build his confidence. ”In hindsight, I feel like a cat with seven lives,” he said of his nomadic career. “That’s why when I go to the zoo, I spend most of my time with the tigers. I look for inspiration in them.” He eventually settled with Viktoria Plzen, where his career took off, leading to a move to Slavia Prague in 2024."}, special: "'El Tigre'" },
  { number: 23, name: 'Lukas Hornicek', position: 'GK', age: 23, club: 'Braga', bio: {"es":"Hornicek ha pasado aproximadamente un tercio de su vida en Portugal, donde se mudó a los 17 años. Vivía en un internado a 2.400 kilómetros de casa y sentía nostalgia, pero nunca renunció a su sueño de una carrera en el fútbol. \"Esa decisión me quitó parte de la juventud que podría haber pasado con amigos, pero seguí mi sueño. Aunque pudiera retroceder el tiempo, no lo cambiaría\", afirma. Apodado “Checo Cachondo” en Portugal debido a la dificultad de pronunciar su apellido, ahora es una estrella en ascenso entre los porteros checos. Comenzó en el equipo juvenil de Braga y pasó dos años como suplente, antes de lograr un avance espectacular la temporada pasada. Mantuvo la portería a cero cada dos partidos y se hizo conocido por salvar penaltis en la Europa League. Con una gran concentración, ha mejorado su distribución y trabajo con el balón en Portugal e incluso se le ha relacionado últimamente con el Real Madrid. \"Es una pena que mi abuelo no viviera para ver [esto]. Fue mi mayor apoyo\", dice.","en":"Hornicek has spent roughly a third of his life in Portugal, where he moved aged 17. He was based in a boarding school 1,500 miles from home and was homesick, but never gave up his dream of a career in football. “That decision took away part of the youth I could have spent with friends, but I followed my dream. Even if I could turn back time, I wouldn’t change it,” he says. Nicknamed “Horny Czech“ in Portugal because of the difficulty of pronouncing his surname, he’s now a rising star in Czech goalkeeping. He started in Braga’s youth team and spent two years as a backup, before a spectacular breakthrough last season. He kept a clean sheet every other match and became known for saving penalties in the Europa League. Boasting high levels of concentration, he has improved his distribution and work on the ball in Portugal and has even been linked with Real Madrid of late. “It’s a shame my grandfather didn’t live to see [this]. He was my biggest supporter,” he says."} },
  // Defensores
  { number: 2, name: 'David Zima', position: 'DF', age: 25, club: 'Slavia Prague', bio: {"es":"Zima puede parecer un joven bastante inusual, especialmente en sus apariciones públicas. A primera vista, no se puede saber qué tipo de día está teniendo. Después de la primera pregunta, todavía no sabes cómo irá la entrevista. Zima –que significa “invierno”– no es una estrella llamativa, a pesar de que su carrera despegó rápidamente cuando era adolescente. A los 19 años, con sólo 156 minutos en la liga nacional, fue fichado por el Slavia Praga procedente del Sigma Olomouc por más de 1 millón de euros, una cifra rara vez vista en el fútbol checo para un jugador así. La medida no lo desconcertó. \"No tengo motivos para estar nervioso\", dijo. \"El campo es siempre del mismo tamaño. Los rivales no me asustan\". Un año y medio después, se mudó a Italia por cuatro veces esa tarifa, fichando por el Torino. En enero de 2024, regresó al Slavia Praga para reiniciar su carrera y, con 4 millones de euros, se convirtió en el fichaje más caro de la historia de la liga checa. Ahora, cuatro veces campeón de la liga nacional, es ampliamente elogiado por su enfoque preciso en la defensa, aunque los críticos todavía dicen que puede ser demasiado relajado y propenso a fallas defensivas.","en":"Zima can come across as a rather unusual young man, especially in his public appearances. At first glance, you cannot tell what kind of day he’s having. After the first question, you still don’t know how the interview will go. Zima – meaning “winter” – is not a flashy star, despite the fact his career quickly took off as a teenager. At 19, with just 156 minutes in the domestic league, he was signed by Slavia Prague from Sigma Olomouc for more than €1m, a fee rarely seen in Czech football for such a player. The move did not faze him. “I have no reason to be nervous,” he said. “The pitch is always the same size. Opponents don’t scare me.” A year and a half later, he moved to Italy for four times that fee, joining Torino. In January 2024, he returned to Slavia Prague to restart his career and, at €4m, became the most expensive signing in Czech league history. Now a four-time domestic league champion, he is widely praised for his precise approach to defending, though critics still say he can be too laid back, and prone to defensive lapses."} },
  { number: 3, name: 'Tomas Holes', position: 'DF', age: 33, club: 'Slavia Prague', bio: {"es":"Los aficionados a la anatomía humana deberían echar un vistazo a Tomas: el central tiene lo que bien podrían ser las pantorrillas más grandes del torneo. No es particularmente alto, pero es puro músculo. También es uno de los jugadores con más experiencia de la selección checa y es un líder silencioso en el Slavia Praga, donde ha ganado cuatro títulos de liga, el último como capitán. Proviene de una región donde el esquí de fondo es más común que el fútbol, ​​pero se enamoró de este juego compitiendo con sus dos hermanos. Al no tener un campo adecuado en su pueblo, solía recorrer cinco kilómetros en bicicleta para ir a entrenar. A través de constancia y trabajo duro, Holes se ha convertido gradualmente en un líder sin actuar nunca como una superestrella. A pesar de que Chequia es un país mayoritariamente laico, es un cristiano evangélico devoto y dice: \"Para mí, la fe es lo más importante, además de mi familia. A menudo siento que los ángeles de la guarda me ayudan en el campo\". Lejos del campo, Holes disfruta de una vida tranquila con sus dos hijas, a menudo va a pescar y lee libros de historia antes de acostarse.","en":"Fans of human anatomy should take a look at Tomas: the centre-back has what may well be the biggest calves at the tournament. He’s not particularly tall, but is pure muscle. He’s also one of the most experienced players in the Czech squad and is a quiet leader at Slavia Prague, where he has won four league titles, the latest as captain. He comes from a region where cross-country skiing is more common than football but fell in love with the game competing with his two brothers. With no proper pitch in his village, he used to cycle three miles to training. Through consistency and hard work, Holes has gradually developed into a leader without ever acting like a superstar. Despite Czechia being a largely secular country, he is a devout evangelical Christian and says: “Faith is the most important thing for me, apart from my family. I often feel like guardian angels help me on the pitch.” Away from the pitch, Holes enjoys the quiet life with his two daughters, often going fishing and reading history books before bed."}, special: "Quiet leader" },
  { number: 4, name: 'Robin Hranac', position: 'DF', age: 26, club: 'Hoffenheim', bio: {"es":"Hranac creció en una pequeña ciudad del oeste de Chequia, lejos de las principales academias, así que cuando su talento quedó claro, eso tuvo que cambiar. A los 14 años, viajó 60 millas hasta un internado en Plzen mientras sus padres trabajaban al otro lado de la frontera, en Alemania. Los sacrificios dieron sus frutos. Hoy en día tiene un exterior tranquilo y reservado, y puede parecer tímido, pero eso disfraza la verdadera lucha y pasión que lleva dentro. \"Robin recibe muchos golpes pero nunca reacciona ni se enoja\", dice su padre. \"Tiene un umbral de dolor extremadamente alto\". Después de solo una temporada impresionante en la liga checa, irrumpió en la selección nacional, marcó a Cristiano Ronaldo en la Eurocopa 2024 y obtuvo un traslado de 8 millones de euros al Hoffenheim en 2024. Lo mejor es jugar en el medio de una zaga de tres.","en":"Hranac grew up in a small town in western Czechia, far from major academies – so when his talent became clear, that had to change. At 14, he travelled 60 miles to a boarding school in Plzen while his parents worked across the border in Germany. The sacrifices paid off. These days he has a calm and reserved exterior, and can appear shy, but that disguises the real fight and passion inside him. ”Robin takes a lot of hits but never reacts or gets angry,” says his dad. “He has an extremely high pain threshold.” After just one impressive season in the Czech league he broke into the national team, marked Cristiano Ronaldo at Euro 2024, and earned an €8m move to Hoffenheim in 2024. Best deployed in the middle of a back three."}, special: "High pain threshold" },
  { number: 5, name: 'Vladimir Coufal', position: 'DF', age: 33, club: 'Hoffenheim', bio: {"es":"Pasado por alto durante mucho tiempo debido a su complexión delgada, a los 17 años los entrenadores del club checo Banik Ostrava le dijeron a Coufal que nunca se ganaría la vida con el fútbol. Era rápido y decidido, pero demasiado pequeño y fácilmente superable en los duelos. En aquella época odiaba el fútbol. \"Pero me prometí a mí mismo que les demostraría que todos estaban equivocados. Soy un poco loco al que le gusta perseguir sus sueños\", dijo. El verdadero reconocimiento sólo llegó a los 26 años, cuando fue fichado por el Slavia Praga y ganó tres títulos de liga consecutivos antes de dar un paso sorpresa a la Premier League. \"Al principio pensé que se habían equivocado de nombre. ¿Por qué contratarían a un veterano?\". Bromeó sobre su traslado al West Ham. En Londres disfrutó de una etapa de cuento de hadas que culminó con la victoria en la Europa Conference League. Pero después de cinco años se encontró en la periferia de los Hammers. Sin embargo, una vez más se negó a darse por vencido. Ahora, con 33 años, ha reconstruido su carrera en Hoffenheim y podría decirse que está jugando su mejor fútbol.","en":"Long overlooked due to his slight build, Coufal was told at 17 by coaches at Czech club Banik Ostrava that he would never make a living from football. He was quick and determined, but too small and easily outmuscled in duels. At that time, he hated football. “But I promised myself I’d prove them all wrong. I’m a bit of a madman who likes chasing his dreams,” he said. True recognition only came at 26, when he was signed by Slavia Prague and went on to win three consecutive league titles before making a surprise move to the Premier League. “At first I thought they had the wrong name. Why would they sign a veteran?” he joked of his move to West Ham. In London he enjoyed a fairytale spell, culminating in winning the Europa Conference League. But after five years he found himself on the periphery with the Hammers. Again, though, he refused to give up. Now 33, he has rebuilt his career at Hoffenheim and is playing arguably his best football."}, special: "Self-confessed 'mad man'" },
  { number: 6, name: 'Stepan Chaloupek', position: 'DF', age: 22, club: 'Slavia Prague', bio: {"es":"Una de las estrellas emergentes de la reciente temporada de la liga checa, uno de los mejores defensores absolutos del país y campeón con el Slavia, las actuaciones de Chaloupek fueron tales que atrajo el interés de la Roma y la Fiorentina en enero. Un año antes, sin embargo, ni siquiera estaba en el once titular después de un momento difícil debido a una lesión. Es un defensor trabajador, disciplinado y confiable: una pesadilla para los atacantes debido a su estilo intransigente. Fuera del campo es tranquilo y reservado. Si el fútbol no hubiera funcionado, dice que podría haberse convertido en policía. \"Me gustó la idea de ser justo, tener principios y defender la verdad\", dice. Chaloupek nació con paladar hendido y fue operado a la edad de tres años. \"Otros niños se burlaban de mí por eso. Fue difícil, pero me hizo más fuerte\". Más tarde consideró la posibilidad de someterse a una cirugía plástica, ya que todavía respira por una sola fosa nasal.","en":"One of the breakout stars of the recent Czech league season, one of the country’s best out-and-out defenders and a champion with Slavia, Chaloupek’s performances were such that he attracted interest from Roma and Fiorentina in January. A year earlier, however, he wasn’t even in the starting lineup after a tough time with injury. He’s a hard-working, disciplined and reliable defender – a nightmare for attackers due to his uncompromising style. Off the pitch, he is quiet and reserved. Had football not worked out, he says he might have become a police officer. “I liked the idea of being fair, principled and standing up for the truth,” he says. Chaloupek was born with a cleft palate and underwent surgery at the age of three. “I was mocked by other kids because of it. It was hard, but it made me stronger.” He later considered plastic surgery as he still breathes through only one nostril."} },
  { number: 7, name: 'Ladislav Krejci', position: 'DF', age: 27, club: 'Wolves', captain: true, bio: {"es":"El sueño de infancia de Krejci de jugar en la Premier League se convirtió en una especie de pesadilla la temporada pasada cuando los Wolves sufrieron derrota tras derrota, sufriendo el descenso al campeonato. Sin embargo, el central se ha convertido rápidamente (y para sorpresa de algunos) en uno de los jugadores más valiosos de Rob Edwards. En los últimos cuatro años, su ascenso ha sido rápido. Ganó dos títulos de liga con el Sparta Praga, se convirtió en el fichaje más caro de la historia del Girona, antes de ser cedido a la Premier League el verano pasado. Krejci sigue un lema simple: \"Si sientes que debes hacer, decidir o cambiar algo, no lo dudes. Nadie más lo hará por ti\". Solía ​​​​luchar con la disciplina y recibía demasiadas tarjetas amarillas. Sin embargo, desde marzo es capitán de la selección nacional y lideró con distinción, anotando en los partidos de playoffs contra la República de Irlanda y Dinamarca. “Creí en mí mismo porque sé lo que puedo hacer”, afirmó el joven de 27 años.","en":"Krejci’s childhood dream of playing in the Premier League turned into something of a nightmare last season as Wolves endured defeat after defeat, suffering relegation to the Championship. The centre-back, however, has quickly – and to the surprise of some – turned into one of Rob Edwards’ most valuable players. Over the past four years, his rise has been rapid. He won two league titles with Sparta Prague, became the most expensive signing in Girona’s history, before a loan to the Premier League last summer. Krejci follows a simple motto: ”If you feel you should do, decide or change something, don’t hesitate. No one else will do it for you.” He used to struggle with discipline and picked up too many yellow cards. Yet since March, he has been captain of the national team and led with distinction, scoring in the playoff games against Republic of Ireland and Denmark. “I believed in myself because I know what I can do,” said the 27-year-old."}, special: "Decisive" },
  { number: 14, name: 'David Jurasek', position: 'DF', age: 25, club: 'Slavia Prague', bio: {"es":"Cuando Jurasek se mudó del Slavia Praga al Benfica por 14 millones de euros hace tres años, convirtiéndose en una de las exportaciones más caras de la liga checa, parecía que el fútbol checo finalmente tendría un lateral en un club europeo importante. Su padre incluso voló a Portugal en un jet privado para la ceremonia de firma, ya que el Benfica fijó su cláusula de rescisión en la friolera de 80 millones de euros, una indicación del respeto que le tenían. Sin embargo, una grave lesión en el tobillo frenó su evolución y perdió su puesto en el primer equipo del Benfica. Jurasek reconstruyó su carrera durante una cesión en el Hoffenheim, antes de regresar al Slavia en enero. “Sólo espero no traer mala suerte”, confesó antes de ayudarles a conseguir el título de liga, el primer título de su carrera. Con un fuerte pie izquierdo, excelente resistencia y aceleración, una gran presencia física y una gran habilidad para cruzar, Jurasek tiene casi todos los atributos que desearías de un lateral izquierdo.","en":"When Jurasek moved from Slavia Prague to Benfica for €14m three years ago, becoming one of the Czech league’s most expensive exports, it seemed Czech football would finally have a full-back at a top European club. His father even flew to Portugal by private jet for the signing ceremony, as Benfica set his release clause at a whopping €80m, an indication of the regard in which they held him. However, a serious ankle injury disrupted his progress, and he lost his place in the Benfica first team. Jurasek rebuilt his career during a loan spell at Hoffenheim, before returning to Slavia in January. “I just hope I don’t bring bad luck,” he confessed before helping them to the league title – the first title success of his career. With a strong left foot, excellent stamina and acceleration, a big physical presence and a great crossing ability, Jurasek has just about every attribute you would want from a left-back."} },
  { number: 20, name: 'Jaroslav Zeleny', position: 'DF', age: 33, club: 'Sparta Prague', bio: {"es":"Uno de los pocos futbolistas selectos a quienes los aficionados han perdonado por jugar en ambos clubes rivales de Praga. Zeleny, de carácter afable, no es en absoluto un rebelde ni un alborotador, pero puede ser impaciente, sobre todo cuando conduce su coche. “Me molesta cuando alguien se entretiene ante las luces porque está hablando por teléfono”, dice. \"Ahí es cuando toco la bocina. De lo contrario, estoy tranquilo. La gente dice que en el fútbol de alto nivel hay que ser despiadado, pero no está en mi naturaleza\". Es poco probable que Zeleny cambie su carácter ahora que se acerca su cumpleaños número 34. Nunca ha abandonado la liga checa y ha disputado más de 300 partidos desde su debut con el Hradec Kralove en 2010. Al principio de su carrera, es posible que le faltara el coraje para mudarse al extranjero; Ahora se acerca el final de su etapa como figura imperecedera del fútbol checo. Oportunamente, su apellido se traduce como \"verde\" en inglés.","en":"One of the select few footballers who fans have forgiven for playing for both rival Prague clubs. An easy-going character, Zeleny is in no way a rebel or troublemaker, but he can be impatient, particularly when driving his car. “It annoys me when someone dawdles at the lights because they are on their phone,” he says. “That’s when I lean on the horn. Otherwise, I’m calm. People say you need to be ruthless in top football, but it’s not in my nature.” Zeleny is unlikely to change his nature now as he approaches his 34th birthday. He has never left the Czech league, making over 300 appearances since his debut for Hradec Kralove in 2010. Earlier in his career, he may have lacked the courage to move abroad; now he’s nearing the end of his time as an evergreen of Czech football. Fittingly, his surname translates to “green” in English."}, special: "Angry driver" },
  { number: 21, name: 'David Doudera', position: 'DF', age: 28, club: 'Slavia Prague', bio: {"es":"Al igual que su compañero de equipo en el Slavia, Tomas Chory, Doudera disfrutó de un animado derbi de Praga en mayo, en el que ambos recibieron tarjetas rojas mientras el partido se convertía en un caos de violencia entre el público. La roja de Doudera fue por abusar del árbitro; El presidente del Slavia, Jaroslav Tvrdik, respondió incluyéndolo en la lista de transferencias. Más tarde, el defensa se disculpó y escribió en línea: \"Lamento toda la situación. A los aficionados, a todo el Slavia, al fútbol checo. Estas cosas no deberían suceder en un mundo civilizado\". Ahora tiene la oportunidad de redimirse este verano. Hizo su debut internacional en 2023, un año después de su traslado al Slavia. Poco después dijo: \"Mi papá y yo siempre decimos que mi historia vale un libro. Pero no quiero alardear de ello, es sólo que la tengo en mí. Cada uno de nosotros tiene una historia y cada uno llegó hasta aquí de alguna manera. No tuve un gran talento desde muy joven. Nunca estuve en las selecciones juveniles... Estoy orgulloso de mí mismo por lo que he logrado\". Su compañero de equipo Lukas Cerv es su primo.","en":"Like his Slavia teammate Tomas Chory, Doudera had a lively Prague derby in May, with both shown red cards as the game descended into a mess of crowd violence. Doudera’s red was for abusing the referee; Slavia’s chairman, Jaroslav Tvrdik, responded by transfer-listing him. The defender later apologised, writing online: \"I'm sorry for the whole situation. To the fans, to the whole of Slavia, to Czech football. These things shouldn't happen in a civilised world.” He now has a chance to redeem himself this summer. He made his international debut in 2023, a year after his move to Slavia. He said soon afterwards: “My dad and I always say that my story is worth a book. But I don't want to brag about it, it's just that I have it in me. Each of us has a story and everyone got here somehow. I wasn't a great talent from a young age. I was never in the youth national teams … I'm proud of myself for what I've accomplished.” Teammate Lukas Cerv is his cousin."} },
  // Volantes
  { number: 8, name: 'Vladimír Darida', position: 'MF', age: 35, club: 'Hradec Kralove', bio: {"es":"De carácter modesto, cuando Darida jugó en el Friburgo de 2013 a 2015, iba a entrenar en scooter. Sin embargo, se deshizo de él cuando se mudó a Berlín con el Hertha. \"En el tráfico de Berlín no era realmente seguro\", afirmó. “Mi padre se lo llevó a Chequia y se lo regalé a mi hermana”. No fue un viaje fácil hacia el fútbol profesional: casi tuvo que abandonar el juego cuando tenía 16 años cuando su crecimiento se detuvo, dejándolo luchando por manejar el aspecto físico del juego. Pero, gracias al trabajo duro y a una dieta sin gluten, desarrolló la fuerza necesaria. Pasó siete años en Hertha antes de mudarse a Aris en Grecia en 2022 y regresar a Chequia el año pasado con Hradec Kralove. Aporta una gran experiencia, ya que hizo su debut internacional en 2012 y fue capitán del equipo en la Eurocopa 2020. Después de ese torneo, se retiró del fútbol internacional y dijo: “Viví momentos hermosos en la selección nacional, pero ahora me gustaría pasar mucho más tiempo con mi familia y mi hijo pequeño”. Pero en marzo de este año estuvo tentado y regresó, a los 35 años, para ayudarlos en los play-offs de clasificación para la Copa del Mundo.","en":"An unassuming character, when Darida played for Freiburg from 2013 to 2015 he rode a scooter to training. He got rid of it when he moved to Berlin with Hertha, though. “It wasn’t really safe in Berlin traffic,” he said. “My father took it back to Czechia and I gave it to my sister.” It wasn’t an easy journey into professional football: he almost had to quit the game when he was 16 when his growth stopped, leaving him struggling to handle the physicality of the game. But, via hard work and a gluten-free diet, he developed the strength needed. He spent seven years at Hertha before moving to Aris in Greece in 2022, and returning to Czechia last year with Hradec Kralove. He brings huge experience, having made his international debut back in 2012, and captained the team at Euro 2020. After that tournament he retired from international football, saying: “I experienced beautiful moments in the national team, but now, I’d like to spend much more time with my family and my young son.” But he was tempted back in March this year, returning, aged 35, to help them in the World Cup qualification play-offs."} },
  { number: 12, name: 'Lukas Cerv', position: 'MF', age: 24, club: 'Viktoria Plzen', bio: {"es":"Primo de su compañero de equipo David Doudera, Cerv hizo su debut internacional hace dos años, poco después de unirse al Viktoria Plzen procedente del Slovan Liberec, y fue el único recién llegado al equipo nacional para la Eurocopa 2024. No esperaba la llamada cuando llegó. “Al principio realmente no lo creía”, dijo tras llegar al campo de entrenamiento del equipo. \"Me fui de vacaciones, así que cuando recibí la llamada tuve que dejar a mi familia allí y volar. Los dejé allí para disfrutar del calor y el sol. Y aquí estamos bajo la lluvia y la niebla. Pero es realmente increíble\". Sin embargo, adaptarse a la configuración nacional no fue demasiado difícil: \"Conozco a muchos muchachos de la sub-21 y tengo a Doudis [Doudera], mi primo y los muchachos de Plzen aquí, así que todo está bien. Pero probablemente salgo más con Doudis\". Dos años después, está completamente integrado y es una opción experimentada y confiable para este equipo de la Copa del Mundo. Su apellido se traduce como \"gusano\".","en":"Cousin of teammate David Doudera, Cerv made his international debut two years ago, soon after joining Viktoria Plzen from Slovan Liberec, and was the only newcomer in the national side’s Euro 2024 squad. He wasn’t expecting the call when it came. “I didn’t really believe it at first,” he said after arriving at the team’s training camp. “I went on vacation, so when I got the call I had to ​​leave my family there and fly away. I left them there to enjoy the warmth and sunshine. And here we are in the rain and fog. But it's really incredible.\" Settling in as part of the national set-up wasn’t too hard, though: “I know a lot of guys from the Under-21s and I have Doudis [Doudera], my cousin, and the guys from Plzen here, so everything is fine. But I'm probably hanging out with Doudis most.” Two years on and he’s fully integrated, and an experienced, reliable option for this World Cup squad. His surname translates as “worm”."} },
  { number: 15, name: 'Pavel Sulc', position: 'MF', age: 25, club: 'Lyon', bio: {"es":"Ampliamente relacionado con un gran movimiento después de este torneo: este verano es una oportunidad real para que Sulc muestre su talento. Poco después de ser elegido mejor jugador checo de 2025, fichó por el Lyon procedente del Viktoria Plzen por 7,5 millones de euros iniciales y tuvo la formidable tarea de llenar el vacío dejado por Rayan Cherki. Pero hizo caso omiso de esa presión y dio un paso adelante con algunas exhibiciones magníficas, ganándose muchos elogios de los seguidores. La acogida le sorprendió. \"Ha sido increíble\", dijo en abril. \"Honestamente, no esperaba tanto cariño de los aficionados ni que sucediera tan rápido... Es mi primera experiencia en una de las cinco ligas más importantes de Europa, y el fútbol en Chequia es mucho menos exigente. El entrenador ha sido brillante conmigo\". Él también está feliz de ser versátil. “¡Siempre haré lo mejor que pueda, incluso si me ponen de central!”","en":"Widely linked with a big move after this tournament – this summer is a real chance for Sulc to showcase his talents. Soon after being voted the best Czech player of 2025 he joined Lyon from Viktoria Plzen for an initial €7.5m, handed the formidable task of filling the void left behind by Rayan Cherki. But he shrugged off that pressure and stepped up with some superb displays, earning plenty of praise from supporters. The reception surprised him. “It’s been incredible,” he said in April. “Honestly, I didn't expect so much love from fans or that it would happen so quickly … It’s my first experience in one of the top five leagues in Europe, and the football in Czechia is simply much less demanding. The coach has been brilliant with me.” He’s happy to be versatile, too. “I'll always do my best, even if they put me as a centre-back!”"}, special: "Going places" },
  { number: 18, name: 'Michal Sadilek', position: 'MF', age: 27, club: 'Slavia Prague', bio: {"es":"A los 16 años, Sadilek hizo un movimiento audaz. En lugar de seguir a su hermano mayor Lukas a través del sistema académico en su país de origen, se fue a Holanda y se unió al PSV. Quizás el tiempo separados les hizo bien. “Cuando éramos niños estábamos juntos todos los días”, recuerda Michal, “y a veces, como todos los niños pequeños, nos poníamos de los nervios, peleábamos y cosas por el estilo”. Pero estos días no podrían estar más cerca. \"Estoy orgulloso de mi hermano. Nos escribimos después de cada partido y, cuando tenemos la oportunidad, hablamos de todo\". Se mudó al Twente en 2022 por tres años, antes de regresar a casa con el Slavia en 2025. Su carrera internacional no ha estado exenta de altibajos: debutó en 2021, pero tuvo que retirarse de la Eurocopa 2024 después de lesionarse la pierna al caerse de su triciclo en el campo de entrenamiento. La FA dijo que el incidente ocurrió cuando condujo la bicicleta de tres ruedas por un bache y se estrelló, pero no lo criticaron. \"El accidente ocurrió en el tiempo libre del jugador, que podía utilizar como quisiera. No violó las reglas del equipo ni otros acuerdos internos\".","en":"At 16, Sadilek made a bold move. Instead of following his older brother Lukas through the academy system in his home country, he left for the Netherlands, joining PSV. Maybe the time apart did them good. “As kids we were together every day,” remembered Michal, “and sometimes like all little boys we got on each other's nerves, fought and the like.” But these days they couldn’t be closer. “I’m proud of my brother. We write to each other after every match, and when there's a chance, we talk about everything.” He moved to Twente in 2022 for three years, before returning home with Slavia in 2025. His international career hasn’t been without its ups and downs: he made his debut in 2021 but had to pull out of the Euro 2024 squad after injuring his leg when he fell off his tricycle at the training camp. The FA said the incident happened when he drove the three-wheeled bike through a pothole and crashed, but they didn’t criticise him. “The accident happened in the player's free time, which he was allowed to spend as he pleased. He did not violate team rules or other internal agreements.\""}, special: "Adventurous" },
  { number: 22, name: 'Tomas Soucek', position: 'MF', age: 31, club: 'West Ham', bio: {"es":"No fue una temporada fácil para Soucek, ya que el West Ham tuvo problemas, pero sigue siendo una parte fundamental de la selección nacional de Miroslav Koubek: una fuerza brillantemente enérgica de 1,93 m en el mediocampo. El año pasado fue nombrado por cuarta vez Futbolista checo del año. Se crió en Havlickuv Brod, una ciudad con una población de 23.000 habitantes, y proviene de una familia de deportistas: su padre es entrenador de fútbol y su madre corredora. “Ella corre medias maratones y maratones y, a veces, cuando yo era más joven, iba con ella al bosque”, dice. \"Y a veces, cuando estaba en pretemporada, iba con ella a correr por el bosque. Creo que obtuve mi resistencia de ella\". El año pasado publicó su autobiografía, en la que reveló que había considerado jubilarse anticipadamente durante lo que fueron “dos años de horror” pasados ​​con insomnio y depresión. Mejoró con ayuda médica y dijo que su característica celebración de gol en \"helicóptero\" surgió de la experiencia: \"De partido en partido, me concentraba principalmente en no dormir, lo que en realidad me molestaba doblemente. Y es por eso que se creó el helicóptero, mi celebración de gol. Empiezo a girar un poco y disfruto la sensación de despegar. Me gusta cuando los fanáticos me llaman helicóptero. Es un símbolo de lo que he hecho, lo que he superado y dónde estoy. Expresa mi sentimiento interno de que puedo luchar\".","en":"It wasn’t an easy season for Soucek as West Ham struggled, but he remains a fundamental part of Miroslav Koubek’s national side – a brilliantly energetic 1.93m force in midfield. Last year he was named Czech Footballer of the Year for the fourth time. He was brought up in Havlickuv Brod, a town with a population of 23,000 people, and comes from a sporting family: his dad a football coach and his mum a runner. “She runs half-marathons and marathons and sometimes when I was younger I went with her to the forest,” he says. “And sometimes when I was in pre-season I would go with her to run in the forest. I think I got my stamina from her.” Last year he published his autobiography, in which he revealed he had considered retiring early during what were “two years of horror” spent with insomnia and depression. He improved with medical help, and said his trademark “helicopter” goal celebration rose from the experience: “From match to match, I focused mainly on not sleeping, which actually disturbed me doubly. And that’s why the helicopter was created, my goal celebration. I start to spin slightly and enjoy the feeling of taking off. I like it when fans call me a helicopter. It’s a symbol of what I’ve done, what I’ve overcome, and where I am. It expresses my inner feeling that I can fight.”"}, special: "Midfield engine" },
  { number: 24, name: 'Alexandr Sojka', position: 'MF', age: 23, club: 'Viktoria Plzen', bio: {"es":"Criado en una familia de futbolistas. El padre de Sojka, Jindrich, fue presidente del SK Klatovy durante más de 20 años y su hermano mayor juega ahora para ellos. Sin embargo, Alexandr es el que ha llegado más lejos en la familia. Regresó a su primer club, el Viktoria Plzen, este año cuando activaron una cláusula de recompra, recontratándolo procedente del Hradec Kralove. “Decidimos activar la opción”, afirmó el director deportivo del club, Martín Vozábal. \"El objetivo es aumentar la competencia en el centro del campo y él tuvo un muy buen desempeño durante el otoño\". Ha demostrado ser un intérprete versátil y dotado técnicamente. Su inclusión internacional fue un momento abrumador para su papá. \"Toda la familia vive para ello\", dijo Jindrich a iSport. \"La única lástima es que su abuelo, un gran aficionado del Plzen desde pequeño, no vivió para verlo. Sasa [Alexandr] finalmente está mostrando lo que hay en él. La gente de esta región vive para el fútbol y aprecia que un chico de Klatovy pueda alcanzar tal nivel\".","en":"Raised in a footballing family. Sojka’s dad Jindrich was chairman of SK Klatovy for over 20 years, and his older brother plays for them now. Alexandr has gone the furthest in the family, though. He returned to his first club, Viktoria Plzen, this year when they activated a buy-back clause, re-signing him from Hradec Kralove. “We decided to activate the option,\" said the club’s sporting director, Martin Vozábal. \"The goal is to increase competition in midfield and he performed very well during the autumn.” He has proved himself as a technically-gifted, versatile performer. His international inclusion was an overwhelming moment for his dad. \"The whole family lives for it,” Jindrich told iSport. “The only pity is that his grandfather, a big fan of Plzen since childhood, did not live to see it. Sasa [Alexandr] is finally showing what is in him. People in this region live for football and they appreciate that a boy from Klatovy can reach such a level.\""} },
  { number: 25, name: 'Hugo Sochurek', position: 'MF', age: 17, club: 'Sparta Prague', bio: {"es":"Sochurek, el pequeño del equipo, tenía todavía 17 años cuando se anunció la selección final. Producto de la academia del Sparta, hizo su debut en el club el año pasado y su debut internacional en un partido de preparación contra Kosovo en mayo. Pero su actitud fría y valiente convenció al entrenador, Miroslav Koubek, de que estaba preparado. Después de su avance con el primer equipo en el Sparta, el entrenador Brian Priske dijo: \"Juega como si tuviera más de 30 años. Los jugadores del primer equipo lo acogieron inmediatamente y vieron lo que podía hacer con el balón\". El entrenador juvenil del Sochurek, Pavel Drsek, dijo a Eurofotbal.cz en mayo: \"Ha mejorado mucho en el último año, ha crecido, tiene muslos fuertes, es difícil sacarlo del balón. No es el típico centrocampista checo, le gusta el balón, su primer pensamiento es ir hacia adelante... Y es un gran tipo, un alma pura, pero tranquila. Una vez le entregué el brazalete de capitán antes de un partido y inmediatamente me dijo \"Me dijo que no podría ser el capitán. No es un líder clásico, pero es claramente una fuerza impulsora\".","en":"The baby of the squad, Sochurek was still 17 when the final selection was announced. A product of Sparta’s academy, he made his club debut last year, and his international debut in a warm-up game against Kosovo in May. But his cool, fearless approach convinced the coach, Miroslav Koubek, he was ready. After his first-team breakthrough at Sparta, coach Brian Priske said: “He plays like he's over 30. The first-team players immediately took him in and when they saw what he could do with the ball.” Sochurek’s youth coach Pavel Drsek told Eurofotbal.cz in May: “He's made a huge improvement in the last year, he’s grown bigger, he has strong thighs, it's hard to get him off the ball. He’s not a typical Czech midfielder, he likes the ball, his first thought is to go forward … And he's a great guy, a pure soul, but quiet. Once I handed him the captain's armband before a match and he immediately told me that he could not be the captain. He is not a classic leader, but he is clearly a driving force.”"}, special: "Wonderkid" },
  { number: 26, name: 'Denis Visinsky', position: 'MF', age: 23, club: 'Viktoria Plzen', bio: {"es":"Un joven lateral prometedor que supo lo que quería desde el primer momento en que chutó un balón. “Jugué por primera vez en el pueblo donde nací, en el AFK Horin, cuando tenía tres años”, recuerda. \"Luego nos mudamos y empecé a jugar en Melník. Cuando tenía seis años, jugamos un torneo en algún lugar, no sé exactamente dónde, y el Slavia de Praga me buscó allí. Así que fui a probar al Slavia y me uní a ellos cuando tenía seis años\". Progresó rápidamente y el año pasado fichó por el Viktoria Plzen procedente del Slovan Liberec. El director deportivo del Viktoria, Daniel Kolar, lo calificó como \"un talento extraordinario, que confirmó con la camiseta del Liberec. A pesar de su corta edad, ya ha jugado casi 80 partidos de liga. Tenemos un plan de desarrollo claro con él y pretendemos llevar su potencial aún más lejos\". Dotado técnicamente, tiene ritmo y buen ojo para el gol, una opción útil este verano. Se modela a partir de Kevin De Bruyne.","en":"A promising young winger who knew what he wanted from the moment he first kicked a ball. “I first played in the village where I was born, for AFK Horin, at the age of three,” he recalled. “Then we moved and I started playing for Melník. When I was six, we played a tournament somewhere, I don't know where exactly, and Slavia Prague scouted me there. So I went to Slavia for a trial and joined them when I was six.” He made rapid progress, and last year signed for Viktoria Plzen from Slovan Liberec. Viktoria’s sporting director, Daniel Kolar, called him “an extraordinary talent, which he confirmed in the Liberec jersey. Despite his still young age, he has already played almost 80 league matches. We have a clear development plan with him and we intend to push his potential even further.” Technically gifted, he has pace and an eye for goal – a useful option this summer. Models himself on Kevin De Bruyne."} },
  // Delanteros
  { number: 9, name: 'Adam Hlozek', position: 'FW', age: 23, club: 'Hoffenheim', bio: {"es":"Un verdadero talento, que podría tener un gran impacto. Hlozek juega en Alemania desde 2022, cuando el Bayer Leverkusen tomó nota de su récord en el Sparta de Praga: debutó con la absoluta a los 16 años, marcó 40 goles y dio 36 asistencias en 132 partidos, y ganó la Copa Checa. Se unió por 13 millones de euros iniciales, pero solo permaneció dos años, frustrado con un rol rotativo, y se mudó a Hoffenheim por 17 millones de euros iniciales. Enormemente versátil, es una amenaza por las bandas o por el medio. Es un gran fanático de los tatuajes, con un león gigante en su muslo izquierdo. \"Tiene un significado profundo y personal para mí y me da fuerza\", dijo el año pasado. \"Leo es mi signo zodiacal y me identifico con el animal. El león es conocido por su mentalidad de lucha, exuda un aura y es el rey de la naturaleza. Nos tomó cinco horas y media en la primera sesión, luego tomamos un descanso y después fueron otras cinco horas y media. Pero estoy feliz de haberlo superado. Me gusta mucho\".","en":"A real talent, who could make a big impact. Hlozek has played in Germany since 2022 when Bayer Leverkusen took note of his record at Sparta Prague: a senior debut at 16, scoring 40 goals and making 36 assists in 132 games, and winning the Czech Cup. He joined for an initial €13m, but only stayed for two years, having grown frustrated with a rotational role, moving to Hoffenheim for an initial €17m. Hugely versatile, he’s a threat out wide or through the middle. He’s a big fan of tattoos, with a giant lion on his left thigh. “It has a deep, personal meaning for me and gives me strength,” he said last year. “Leo is my star sign and I identify with the animal. The lion is known for its fighting mentality, exudes an aura and is the king of the wilderness. It took five and a half hours in the first sitting, then we took a break and after that it was another five and a half hours. But I'm happy that I got through it. I like it a lot.\""}, special: "Fan of lions" },
  { number: 10, name: 'Patrik Schick', position: 'FW', age: 30, club: 'Bayer Leverkusen', bio: {"es":"El don goleador de Schick se hizo patente desde muy pequeño. Jugando para Vestec, un pueblo cerca de Praga, no celebraba sus goles, dijeron los entrenadores, sino que simplemente levantaba el balón, lo llevaba al círculo central y pedía que se reanudara el juego. Cuando perdía una gran oportunidad, lloraba y tenía que ser sustituido. A los ocho años se inspiró al ver a Wayne Rooney jugar con el Manchester United en el Sparta Praga. Recordó: “Pensé que quería hacer esto: nunca conseguir un trabajo normal y ganarme la vida como él”. Funcionó bien. Jugó un total de 36 minutos de liga en el primer equipo del Sparta Praga antes de que la Sampdoria decidiera que ya había visto suficiente, pagando 4 millones de euros por el desgarbado joven de 20 años. Fichó por la Roma un año después en una jugada que podría haber valido hasta un récord del club de 42 millones de euros, pero en realidad no funcionó: terminó en el lateral, fue cedido al Leipzig y luego fue vendido al Leverkusen en 2020 por 26,5 millones de euros, que fue donde todo encajó. En abril de este año marcó su gol número 100 en todas las competiciones. Ayudó a la República Checa a clasificarse por primera vez en 20 años a través de los playoffs. Tenía 10 años la última vez que jugaron en un Mundial. \"Recuerdo vívidamente los partidos. Los aficionados checos llevaban mucho tiempo esperando esto\".","en":"Schick’s goalscoring gift was obvious from a very young age. Playing for Vestec, a village near Prague, he didn’t celebrate his goals, said coaches, but would instead just pick the ball up, take it to the centre circle and ask for the game to be resumed. When he missed a big chance, he would cry and had to be substituted. Aged eight he was inspired by watching Wayne Rooney play for Manchester United at Sparta Prague. He recalled: “I thought that I want to do this – never get a normal job, and earn a living like him.” It worked out well. He played a grand total of 36 league minutes in Sparta Prague’s first team before Sampdoria decided they had seen enough, paying €4m for the gangly 20-year-old. He signed for Roma a year later in a move that could have been worth up to a club record €42m, but it didn’t really work out there: he ended up on the wing, was loaned to Leipzig, then was sold to Leverkusen in 2020 for €26.5m - which is where everything clicked. In April this year, he scored his 100th goal for them in all competitions. He helped Czechia qualify for the first time in 20 years via the playoffs. He was 10 when they last played at a World Cup. “I vividly remember the games. The Czech fans have waited a long time for this.”"} },
  { number: 11, name: 'Jan Kuchta', position: 'FW', age: 28, club: 'Sparta Prague', bio: {"es":"Un delantero experimentado que hizo su debut absoluto con el Slavia Praga en 2016 y ahora, una década después, juega con su rival Sparta. Kuchta también estuvo en Rusia con el Lokomotiv de Moscú y en Dinamarca con Midtjylland. La vida con la selección internacional no siempre ha sido fácil: en noviembre de 2023 fue uno de los tres jugadores (junto con Jakub Brabec y Vladimir Coufal) expulsados ​​del campo de entrenamiento por irse de fiesta dos días antes de un partido de clasificación para la Eurocopa 2024 contra Moldavia. Agresivo y poderoso en el campo, se preocupa más fuera de él, criando pollos, conejos, patos y gansos en la granja de su familia. Cuando se mudó a Moscú en 2022 y tuvo que dejarlas atrás, dijo: \"Las gallinas son parte de mi vida, estaba acostumbrado a ir a verlas por la mañana, luego, después del entrenamiento, se me aclaró la cabeza. Me llevará un tiempo adaptarme. No puedo llevarlas allí, hace -17 grados... Las gallinas tendrán que esperar hasta que esté en casa y les volveré a prestar mucha atención\".","en":"An experienced forward who made his senior debut for Slavia Prague back in 2016, and now, a decade later, turns out for rivals Sparta. Kuchta also had spells in Russia with Lokomotiv Moscow and Denmark with Midtjylland. Life with the international side hasn’t always been easy: in November 2023 he was one of three players – with Jakub Brabec and Vladimir Coufal – kicked out of the training camp for going clubbing two days before a Euro 2024 qualifier against Moldova. Aggressive and powerful on the pitch, he’s more nurturing off it, raising chickens, rabbits, ducks and geese at his family farm. When he moved to Moscow in 2022 and had to leave them behind he said: \"Chickens are part of my life, I was used to going to them in the morning, then again after training, it cleared my head. It will take a while to adjust. I can’t take them there, it’s -17 degrees… The chickens will just have to wait until I am home, and I will pay a lot of attention to them again.\""}, special: "Loves chickens" },
  { number: 13, name: 'Mojmir Chytil', position: 'FW', age: 27, club: 'Slavia Prague', bio: {"es":"Chytil, una opción alta y experimentada en la delantera, causó sensación en su debut internacional en 2022, anotando un triplete en diez minutos en un amistoso contra las Islas Feroe. Es conocido por ser físico y valiente, un verdadero puñado, y podría ser un arma importante este verano. Pasó la mayor parte de su carrera inicial en Sigma Olomouc antes de mudarse en 2023 al Slavia Praga, donde, nuevamente, tuvo un debut goleador, anotando contra Hradec Králové en la jornada inaugural. El entrenador del club, Jindrich Trpisovsky, lo describió bien: \"Lo primero que me viene a la mente sobre Mojmir es el beneficio más amplio que aporta al equipo: su espíritu de lucha, su carácter molesto para los defensores. Tiene muy buena cobertura del balón, quizás el mejor juego de espalda a portería de la liga. Es un jugador de equipo, combativo, con excelentes cualidades físicas\".","en":"A tall, experienced option up front, Chytil made quite a splash on his international debut in 2022 - scoring a ten-minute hattrick in a friendly against the Faroe Islands. He’s known for being physical and fearless, a real handful, and could be an important weapon this summer. He spent most of his early career at Sigma Olomouc before 2023’s move to Slavia Prague where, again, he had a scoring debut, netting against Hradec Králové on the opening day. The club’s manager, Jindrich Trpisovsky, described him well: “The first thing that comes to mind about Mojmir is the wider benefit he brings to the team: his fighting spirit, his annoyingness for defenders. He has very good ball coverage, perhaps the best back-to-goal game in the league. He is a team player, combative, with excellent physical qualities.”"} },
  { number: 17, name: 'Lukas Provod', position: 'FW', age: 29, club: 'Slavia Prague', bio: {"es":"Con una presencia imponente de 1,88 m en el exterior, también es veloz. Provod ascendió de rango en el club local Viktoria Plzen, luego tuvo una serie de préstamos mientras se establecía, primero en Banik Sokolov, luego en Ceske Budejovice y finalmente en Slavia Praga, a quien se unió con un contrato permanente en 2020. \"Se siente increíble\", dijo cuando firmó, \"parece una hermosa historia. Todo sucedió muy rápido. Es un gran desafío para mí, y no lo dudé. Slavia es el club más grande y exitoso de Chequia, así que quedó claro de inmediato”. Hizo su debut internacional el mismo año en un partido de la Liga de Naciones contra Eslovaquia. Se perdió la Eurocopa 2020 por lesión, pero entró en la convocatoria de 2024 y marcó en el primer partido contra Portugal. Al ser un intérprete versátil, también se le podría pedir que haga un trabajo más central o adelantado.","en":"An imposing 1.88m presence out wide, he is pacy as well. Provod rose through the ranks at hometown club Viktoria Plzen, then had a series of loans as he established himself, first at Banik Sokolov, then Ceske Budejovice and finally Slavia Prague, whom he joined on a permanent deal in 2020. “It feels unbelievable,” he said when he signed, “it feels like a beautiful story. It all happened really fast. It’s a great challenge for me, and I did not hesitate. Slavia is the biggest and most successful club in Czechia, so it was clear immediately.” He made his international debut the same year in a Nations League game against Slovakia. He missed Euro 2020 due to injury, but made the squad for 2024 and scored in the opener against Portugal. A versatile performer, he could also be called upon to do a job more centrally, or up front."} },
  { number: 19, name: 'Tomas Chory', position: 'FW', age: 31, club: 'Slavia Prague', bio: {"es":"Una potencia de 1,98 m que no tiene miedo de quedarse atrapado. En enero abrazó su imagen de chico malo y dijo: \"¿No le agrado a la gente? Eso realmente me hace sentir bien\". Pero en mayo las cosas llegaron a un punto de inflexión: fue expulsado por darle un codazo a un oponente en la cabeza en un caótico derbi de Praga, su tercera roja roja de la temporada, lo que llevó al furioso presidente del Slavia, Jaroslav Tvrdik, a incluirlo en la lista de transferencias. \"Es evidente que Tomas es incapaz de controlar su comportamiento\", afirmó Tvrdik. \"Con este comportamiento, no pertenece al campo\". El comité disciplinario de la liga lo sancionó por seis juegos, diciendo que el codo \"no fue un evento accidental... ni las emociones ni el estilo de juego asertivo que presenta Tomas Chory pueden ser una excusa para tal acción\". Tiene mucha experiencia y ha pasado toda su carrera en clubes de la República Checa, además de una cesión en Bélgica con el Zulte Waregem. Hizo su debut internacional en 2023, anotando y asistiendo en la victoria por 3-0 sobre Moldavia en las eliminatorias para la Eurocopa 2024.","en":"A 1.98m powerhouse who isn’t afraid of getting stuck in. In January he embraced his bad boy image, saying: “People don’t like me? That actually makes me feel good.” But in May things reached a tipping point: he was sent off for elbowing an opponent in the head in a chaotic Prague derby, his third red of the season, prompting Slavia’s furious chairman, Jaroslav Tvrdik, to transfer-list him. “Tomas is clearly unable to control his behaviour,” said Tvrdik. “With this behaviour, he does not belong on the field.” The league’s disciplinary committee banned him for six games, saying the elbow was “not an accidental event … neither emotions nor the assertive style of play that Tomas Chory presents can be an excuse for such an action”. He has plenty of experience, and has spent his whole club career in Czechia apart from a loan spell in Belgium with Zulte Waregem. He made his international debut in 2023, scoring and assisting in a 3-0 Euro 2024 qualifying win over Moldova."}, special: "Hot-headed" },
];

